mapper.select:
SELECT id, user_id, study_date, status
FROM NC.study_streak_record
WHERE user_id = #{userId}
  AND study_date BETWEEN #{from} AND #{to}
ORDER BY study_date

mapper.update:
UPDATE NC.study_streak_record
SET status = #{status}, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId} AND study_date = #{studyDate}

mapper.select:
SELECT protection_count
FROM NC.study_streak_protection
WHERE user_id = #{userId}

mapper.update:
UPDATE NC.study_streak_protection
SET protection_count = 0, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
